import React, { useState } from "react";
import axios from "axios";

function ATSPanel({ data, jobDesc, setJobDesc }) {
  const [score, setScore] = useState(null);
  const [keywords, setKeywords] = useState([]);
  const [matched, setMatched] = useState([]);
  const [missing, setMissing] = useState([]);
  const [loading, setLoading] = useState(false);

  const analyze = async () => {
    if (!jobDesc || !data.skills) {
      alert("Please enter job description and skills");
      return;
    }

    try {
      setLoading(true);

      // 🔥 FIXED SKILL PARSING (space + comma support)
      const skillsArray = data.skills
        .toLowerCase()
        .split(/[, ]+/)
        .map((s) => s.trim())
        .filter((s) => s);

      console.log("Sending:", { jobDesc, skillsArray });

      const res = await axios.post("http://localhost:5000/api/analyze", {
        jobDesc,
        skills: skillsArray,
      });

      console.log("Response:", res.data);

      setScore(res.data.score);
      setKeywords(res.data.keywords);
      setMatched(res.data.matched || []);
      setMissing(res.data.missing || []);
    } catch (err) {
      console.error("API ERROR:", err);
      alert("Something went wrong. Check backend.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="space-y-4">

      {/* Job Description */}
      <textarea
        className="w-full p-3 border rounded-lg"
        placeholder="Paste Job Description..."
        value={jobDesc}
        onChange={(e) => setJobDesc(e.target.value)}
      />

      {/* Button */}
      <button
        onClick={analyze}
        className="bg-green-500 hover:bg-green-600 text-white px-4 py-2 rounded-lg w-full"
      >
        {loading ? "Analyzing..." : "Analyze Resume"}
      </button>

      {/* Score */}
      {score !== null && (
        <div>
          <p className="font-semibold">ATS Score: {score}%</p>

          <div className="w-full bg-gray-200 h-3 rounded mt-2">
            <div
              className="bg-green-500 h-3 rounded transition-all duration-500"
              style={{ width: `${score}%` }}
            ></div>
          </div>
        </div>
      )}

      {/* Matched Keywords */}
      {matched.length > 0 && (
        <div>
          <h4 className="font-semibold mt-3 text-green-600">
            Matched Skills
          </h4>
          <div className="flex flex-wrap gap-2 mt-2">
            {matched.map((k, i) => (
              <span
                key={i}
                className="bg-green-100 text-green-700 px-2 py-1 rounded"
              >
                {k}
              </span>
            ))}
          </div>
        </div>
      )}

      {/* Missing Keywords */}
      {missing.length > 0 && (
        <div>
          <h4 className="font-semibold mt-3 text-red-600">
            Missing Skills
          </h4>
          <div className="flex flex-wrap gap-2 mt-2">
            {missing.map((k, i) => (
              <span
                key={i}
                className="bg-red-100 text-red-700 px-2 py-1 rounded"
              >
                {k}
              </span>
            ))}
          </div>
        </div>
      )}

      {/* All Keywords */}
      {keywords.length > 0 && (
        <div>
          <h4 className="font-semibold mt-3">Extracted Keywords</h4>
          <div className="flex flex-wrap gap-2 mt-2">
            {keywords.map((k, i) => (
              <span
                key={i}
                className="bg-blue-100 text-blue-700 px-2 py-1 rounded"
              >
                {k}
              </span>
            ))}
          </div>
        </div>
      )}

    </div>
  );
}

export default ATSPanel;
